SELECT CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 2.3 THEN 'mid' ELSE 'low' END AS rating_bucket, city, ROUND((100 * SUM(CASE WHEN country = 'TH' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_th, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(city))) AS city_values, ROUND(STDDEV(rating), 2) AS stddev_rating FROM suppliers GROUP BY CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 2.3 THEN 'mid' ELSE 'low' END, city ORDER BY rating_bucket DESC
